/**
 * pandwind scanner — extracts the classes used by `tw()` calls and writes them
 * to a safelist file that Tailwind's file scanner can see.
 *
 * Tailwind v4 scans source files on disk for literal class candidates, so
 * classes composed at runtime by `tw()` are invisible to it. This script
 * statically evaluates every `tw({ ... })` call in the app source (using the
 * *same* typed `tw` instance the app imports), collects the resulting class
 * strings, and writes them into a generated file:
 *
 * ```ts
 * export const pandwindSafelist = ["bg-sky-600", "sm:flex", ...] as const;
 * ```
 *
 * The file lives inside the scanned source tree, so Tailwind generates CSS for
 * exactly those classes — and nothing more. Parsing uses oxc instead of the TS
 * compiler API: several times faster, and the only thing we need is the AST.
 *
 * Usage:
 *   tsx collect.ts [tw-entry] [src-dir] [out-file]
 *
 * All paths are resolved relative to the current working directory.
 */

import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { parseSync } from "oxc-parser";
import { evalLiteral, isTwCall, walk } from "./literal.ts";

const SOURCE_EXTENSIONS = /\.(ts|tsx)$/;

export function walkDir(dir: string, files: string[] = []): string[] {
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		const path = join(dir, entry.name);
		if (entry.isDirectory()) walkDir(path, files);
		else if (SOURCE_EXTENSIONS.test(entry.name)) files.push(path);
	}
	return files;
}

/**
 * Collect every class string produced by `tw()` calls across `files`.
 *
 * @param files source files to scan
 * @param twEntry absolute path to the app's generated `tw.ts` — its exported
 *   `tw` is the exact instance the app uses, so variant metadata matches.
 */
export async function collectTwClasses(files: string[], twEntry: string): Promise<string[]> {
	const { tw } = (await import(twEntry)) as { tw: (styles: unknown) => string };
	const classes = new Set<string>();

	for (const file of files) {
		const source = readFileSync(file, "utf8");
		const result = parseSync(file, source, {
			sourceType: "module",
			lang: file.endsWith(".tsx") ? "tsx" : "ts",
		});

		walk(result.program, (node) => {
			if (!isTwCall(node)) return;
			for (const argument of node.arguments) {
				const styles = evalLiteral(argument);
				if (styles === undefined) continue;
				try {
					for (const className of tw(styles).split(" ")) {
						if (className) classes.add(className);
					}
				} catch {
					// Unrepresentable call (e.g. a modifier variant without a
					// nested variant) — skip; the runtime will surface it.
				}
			}
		});
	}

	return [...classes];
}

const header = "// Generated by pandwind — do not edit. Run `pnpm tw:scan` to regenerate.";

if (process.argv[1]?.endsWith("collect.ts")) {
	const [twEntryArg, srcDirArg, outFileArg] = process.argv.slice(2);
	const base = process.cwd();
	const twEntry = resolve(base, twEntryArg ?? "src/tw.ts");
	const srcDir = resolve(base, srcDirArg ?? "src");
	const outFile = resolve(base, outFileArg ?? "src/pandwind.safelist.ts");

	const classes = await collectTwClasses(walkDir(srcDir), twEntry);

	// `.css` out-file -> emit Tailwind v4 `@source inline(...)` directives
	// instead of a JS safelist module. Same candidates, no JS import needed:
	// the app imports the generated file from its tailwind.css. Prefer this
	// mode when the app does not want generated JS in its source tree.
	if (outFile.endsWith(".css")) {
		const cssHeader = `/* ${header.replace(/^\/\/\s*/, "")} */`;
		const inlineLines = classes
			.map((className) => `@source inline(${JSON.stringify(className)});`)
			.join("\n");
		const cssContent = `${cssHeader}\n\n${inlineLines}\n`;
		writeFileSync(outFile, cssContent);
		console.log(`pandwind: wrote ${classes.length} @source inline directives to ${outFile}`);
		process.exit(0);
	}

	const content = `${header}
export const pandwindSafelist = [
${classes.map((className) => `\t${JSON.stringify(className)},`).join("\n")}
] as const;
`;
	writeFileSync(outFile, content);
	console.log(`pandwind: wrote ${classes.length} classes to ${outFile}`);
}
